def f(N: int, members: List[Tuple[str, int]], M: int, changes: List[str]) -> int:
    member_dict = defaultdict(int)
    for member in members:
        member_dict[member[0]] += member[1]

    for change in changes:
        change = change.split()
        if change[0] == "+":
            member_dict[change[1]] += int(change[2])
        else:
            member_dict[change[1]] -= 1

    return sum(member_dict.values())
```

